(() => {
 const svg=path=>`<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`;
 const icons={phone:svg('<path d="M5 4h4l2 5-3 2a16 16 0 0 0 5 5l2-3 5 2v4c-8 2-18-8-15-15Z"/>'),mail:svg('<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>'),pin:svg('<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>'),check:svg('<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 2h6v5H9Zm-1 12 3 3 5-6"/>')};
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const button=(label,url,icon='pin')=>`<a class="button secondary" href="${esc(url)}">${label}${icons[icon]}</a>`;
 const cities=['Nicosia','Limassol','Larnaca','Paphos','Paralimni'];
 const topics={vehicle:{label:'Vehicle enquiry',hint:'Tell us which car you have in mind, your budget or any questions about an offer.',placeholder:'I’m interested in…',fields:true},service:{label:'Service & repairs',hint:'Tell us about your car and the maintenance or repair you need.',placeholder:'My car needs…',fields:true},parts:{label:'Parts enquiry',hint:'Include your model and the part you need. The team can confirm compatibility.',placeholder:'I’m looking for…',fields:true},general:{label:'Something else',hint:'Tell us what you need help with.',placeholder:'How can we help?',fields:false}};
 const locations=[
 {city:'Nicosia',type:'sales',name:'Strovolos showroom',brands:'Volkswagen · Škoda · SEAT · CUPRA',address:'9 Megaron Str., 2032 Strovolos',phone:'22366366'},
 {city:'Nicosia',type:'sales',name:'Audi showroom',brands:'Audi',address:'9 Megaron Str., 2032 Strovolos',phone:'22880000'},
 {city:'Limassol',type:'sales',name:'Zakaki showroom',brands:'Volkswagen · Škoda · SEAT',address:'122 Franklin Roosevelt Ave., 3011 Zakaki',phone:'25819799'},
 {city:'Limassol',type:'sales',name:'Audi showroom',brands:'Audi',address:'37 Omonias Ave., 3052 Limassol',phone:'25567577'},
 {city:'Larnaca',type:'sales',name:'Aradippou sales contacts',brands:'Volkswagen · Audi · SEAT · Škoda offices',address:'2 Eleftherias Ave., 7101 Aradippou',phone:'24811033'},
 {city:'Paphos',type:'sales',name:'Paphos offices',brands:'Volkswagen · Audi · Škoda · SEAT',address:'90 Mesogis Ave., 8280 Paphos',phone:'26954626'},
 {city:'Paralimni',type:'sales',name:'Famagusta offices',brands:'Volkswagen · Audi · Škoda · SEAT',address:'71 Sotiras Ave., 5286 Paralimni',phone:'23743888'},
 {city:'Nicosia',type:'service',name:'Latsia workshop & parts',brands:'Volkswagen · Škoda · SEAT',address:'144 Yiannou Kranidioti Ave., 2235 Latsia',phone:'22204222'},
 {city:'Nicosia',type:'service',name:'Body & paint',brands:'Bodywork and paint enquiries',address:'45A Tripoleos Str., 2235 Latsia',phone:'22204192'},
 {city:'Limassol',type:'service',name:'Zakaki workshop & parts',brands:'Workshop and spare-parts enquiries',address:'204 Franklin Roosevelt Ave., 3045 Zakaki',phone:'25827300'},
 {city:'Larnaca',type:'service',name:'Aradippou workshop & parts',brands:'Workshop and spare-parts enquiries',address:'4 Pireos Str., 7101 Aradippou',phone:'24533777'},
 {city:'Paphos',type:'service',name:'Yeroskipou workshop & parts',brands:'Workshop and spare-parts enquiries',address:'13 Charalambou Pettemeride Str., Yeroskipou Industrial Area, 8028',phone:'26967444'}
 ];
 window.uniCarsContactLocations=locations;
 const phone=n=>`+357 ${n.slice(0,2)} ${n.slice(2,5)} ${n.slice(5)}`;
 function locationMarkup(city,type){const list=locations.filter(l=>(city==='all'||l.city===city)&&l.type===type);return {count:list.length,html:list.length?list.map(l=>`<article class="uc-location"><div class="uc-location-copy"><p>${esc(l.city)}</p><h3>${esc(l.name)}</h3><span>${esc(l.brands)}</span><address>${esc(l.address)}</address></div><div class="uc-location-actions">${button(phone(l.phone),'tel:+357'+l.phone,'phone')}<a class="button secondary" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent('Unicars '+l.address+', Cyprus')}" target="_blank" rel="noopener">Directions${icons.pin}</a></div></article>`).join(''):`<div class="uc-no-locations"><h3>Let’s find the right team.</h3><p>No service contact for this city is listed in this directory. Contact head office for help, or choose another city.</p>${button('Call head office','tel:+35722204222','phone')}</div>`};}
 window.renderUniContact=()=>`<div class="uc-contact"><div class="home-frame uc-contact-grid"><section class="uc-contact-intro" aria-labelledby="contactTitle"><p class="uc-contact-crumb">Home / Contact</p><h1 id="contactTitle">Let’s talk.</h1><p class="uc-contact-description">Your next car. The one you drive.<br>Whatever’s on your mind, start here.</p><div class="uc-direct-contact">${button('+357 22 204 222','tel:+35722204222','phone')}${button('info@unicars.com','mailto:info@unicars.com','mail')}</div><details class="uc-office-details"><summary>Head office & opening hours<span aria-hidden="true">+</span></summary><address>144 Yiannou Kranidioti Ave.<br>2235 Latsia, Nicosia, Cyprus</address><p>Monday–Thursday<br><strong>08:30–13:30 · 14:00–17:15</strong></p><p>Friday<br><strong>08:30–13:30</strong></p></details><div class="uc-contact-photo"><img src="assets/support.webp" alt="Škoda photographed beside a modern building" width="900" height="600"><div><p>Here for your next chapter.</p><a class="button uc-photo-button" href="#contactLocations" data-contact-scroll="contactLocations">Find your local team${icons.pin}</a></div></div></section><section class="uc-enquiry" aria-label="Contact Unicars"><div data-wix-form="contact"></div></section></div><section class="uc-contact-locations" id="contactLocations" aria-labelledby="contactLocationsTitle"><div class="home-frame"><div class="uc-location-heading"><div><h2 id="contactLocationsTitle">A team closer to you.</h2><p>Find a sales contact, workshop or parts team.</p></div><a class="button secondary" href="https://www.unicars.com/en/contact.php" target="_blank" rel="noopener">Official contact directory${icons.pin}</a></div><div class="uc-location-filters"><fieldset><legend class="uc-sr">Location type</legend><label><input type="radio" name="contactLocationType" value="sales" checked><span>Showrooms & offices</span></label><label><input type="radio" name="contactLocationType" value="service"><span>Service & parts</span></label></fieldset><label class="uc-city-filter">City<div class="uc-select"><select id="contactCityFilter"><option>Nicosia</option>${cities.slice(1).map(c=>`<option>${c}</option>`).join('')}<option value="all">All cities</option></select><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></div></label><p id="contactLocationCount" role="status">2 locations</p></div><div id="contactLocationResults" class="uc-location-results">${locationMarkup('Nicosia','sales').html}</div><p class="uc-contact-source">Contact details and head-office hours checked against Unicars’ published directory on 19 November 2026. Please confirm opening hours before visiting.</p></div></section></div>`;
 document.addEventListener('click',e=>{const scroll=e.target.closest('[data-contact-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.contactScroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}});
 document.addEventListener('change',e=>{

  if(e.target.matches('[name="contactLocationType"],#contactCityFilter')){const {html,count}=locationMarkup(document.getElementById('contactCityFilter').value,document.querySelector('[name="contactLocationType"]:checked').value);document.getElementById('contactLocationResults').innerHTML=html;document.getElementById('contactLocationCount').textContent=count+' location'+(count===1?'':'s');}
 });
})();
